package com.example.mymed

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase

@Database(
    entities = [MyMedication::class, Reminder::class, MedicationHistory::class],
    version = 3,
    exportSchema = true
)
abstract class AppDatabase : RoomDatabase() {

    abstract fun medicationDao(): MedicationDao

    companion object {
        @Volatile
        private var INSTANCE: AppDatabase? = null

        fun getInstance(context: Context): AppDatabase {
            return INSTANCE ?: synchronized(this) {
                Room.databaseBuilder(
                    context.applicationContext,
                    AppDatabase::class.java,
                    "mymed.db"
                )
                // Deletes DB when schema changes (useful during development)
                // Before release: implement real migrations
                .fallbackToDestructiveMigration(true)
                .build().also { INSTANCE = it }
            }
        }
    }
}

package com.example.mymed

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase
import androidx.room.migration.Migration
import androidx.sqlite.db.SupportSQLiteDatabase

@Database(
    entities = [MyMedication::class, Reminder::class, MedicationHistory::class],
    version = 3,
    exportSchema = true
)
abstract class AppDatabase : RoomDatabase() {

    abstract fun medicationDao(): MedicationDao

    companion object {
        @Volatile
        private var INSTANCE: AppDatabase? = null

        // v2 -> v3: added `snoozeMinutes` to `reminders` (per-reminder snooze interval).
        // Default matches SnoozeManager.DEFAULT_SNOOZE_MINUTES so existing reminders
        // keep working with the previous global default.
        private val MIGRATION_2_3 = object : Migration(2, 3) {
            override fun migrate(db: SupportSQLiteDatabase) {
                db.execSQL(
                    "ALTER TABLE reminders ADD COLUMN snoozeMinutes INTEGER NOT NULL DEFAULT ${SnoozeManager.DEFAULT_SNOOZE_MINUTES}"
                )
            }
        }

        fun getInstance(context: Context): AppDatabase {
            return INSTANCE ?: synchronized(this) {
                Room.databaseBuilder(
                    context.applicationContext,
                    AppDatabase::class.java,
                    "mymed.db"
                )
                    // Real migration: preserves all user data across version 2 -> 3.
                    .addMigrations(MIGRATION_2_3)
                    // Safety net ONLY for a hypothetical pre-repo version 1 DB we have
                    // no schema record of. Any known version (2, 3, ...) uses the
                    // explicit migrations above and never loses data.
                    .fallbackToDestructiveMigrationFrom(1)
                    .build().also { INSTANCE = it }
            }
        }
    }
}

package com.example.mymed

import android.Manifest
import android.content.Intent
import android.content.pm.PackageManager
import android.os.Build
import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.activity.result.contract.ActivityResultContracts
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.Settings
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.tooling.preview.Preview
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import androidx.core.content.ContextCompat
import androidx.lifecycle.lifecycleScope
import androidx.lifecycle.viewmodel.compose.viewModel
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import androidx.navigation.NavHostController
import androidx.navigation.NavType
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import androidx.navigation.navArgument
import com.example.mymed.ui.theme.MyMedTheme
import java.text.SimpleDateFormat
import java.util.*

class MainActivity : ComponentActivity() {

    private val requestPermissionLauncher = registerForActivityResult(
        ActivityResultContracts.RequestPermission()
    ) { isGranted: Boolean ->
        if (isGranted) {
            startMedicationService()
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        requestNotificationPermission()
        // Alarme aus DB neu laden
        lifecycleScope.launch(Dispatchers.IO) {
            AlarmScheduler.rescheduleFromDb(this@MainActivity)
        }

        enableEdgeToEdge()
        setContent {
            MyMedTheme {
                // NavController verwaltet die Navigation zwischen Screens
                val navController = rememberNavController()
                AppNavigation(navController)
            }
        }
    }

    private fun requestNotificationPermission() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            when {
                ContextCompat.checkSelfPermission(
                    this, Manifest.permission.POST_NOTIFICATIONS
                ) == PackageManager.PERMISSION_GRANTED -> startMedicationService()
                else -> requestPermissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS)
            }
        } else {
            startMedicationService()
        }
    }

    private fun startMedicationService() {
        val serviceIntent = Intent(this, MedicationReminderService::class.java)
        startForegroundService(serviceIntent)
    }
}

// --- Navigation Setup ---
// Definiert alle Screens und ihre Routes (Adressen)
@Composable
fun AppNavigation(navController: NavHostController) {
    NavHost(
        navController = navController,
        startDestination = "reminder"   // Startseite
    ) {
        // Screen 1: Erinnerungs-Checkliste (Hauptseite)
        composable("reminder") {
            MedicationReminderScreen(
                onNavigateToMedications = { navController.navigate("medications") }
            )
        }

        // Screen 2: Medikamenten-Liste (CRUD)
        composable("medications") {
            MedicationListScreen(
                onNavigateToDetail = { id -> navController.navigate("medication_detail/$id") },
                onNavigateToAdd = { navController.navigate("medication_detail/-1") },
                onNavigateBack = { navController.popBackStack() }
            )
        }

        // Screen 3: Detail/Add/Edit Screen
        // {id} = Parameter: -1 für Neu, sonst die Medikament-ID
        composable(
            route = "medication_detail/{id}",
            arguments = listOf(navArgument("id") { type = NavType.IntType })
        ) { backStackEntry ->
            val id = backStackEntry.arguments?.getInt("id") ?: -1
            MedicationDetailScreen(
                medicationId = id,
                onNavigateBack = { navController.popBackStack() }
            )
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun MedicationReminderScreen(
    onNavigateToMedications: () -> Unit = {}
) {
    // ViewModel mit DB-Factory erstellen
    val context = LocalContext.current
    val db = remember { AppDatabase.getInstance(context) }
    val viewModel: MedicationViewModel = viewModel(
        factory = MedicationViewModel.factory(
            dao = db.medicationDao(),
            app = context.applicationContext as android.app.Application
        )
    )

    // StateFlow → State (Compose reagiert automatisch auf Änderungen)
    val medications by viewModel.medications.collectAsState()
    val isReminderVisible by viewModel.isReminderVisible.collectAsState()
    val snoozeCountToday by viewModel.snoozeCountToday.collectAsState()

    var showSnoozeDialog by remember { mutableStateOf(false) }
    var currentTime by remember { mutableStateOf(getCurrentTime()) }
    LaunchedEffect(Unit) {
        while (true) {
            kotlinx.coroutines.delay(1000L)
            currentTime = getCurrentTime()
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("MyMed") },
                actions = {
                    IconButton(onClick = onNavigateToMedications) {
                        Icon(Icons.Default.Settings, contentDescription = "Medikamente verwalten")
                    }
                }
            )
        },
        modifier = Modifier.fillMaxSize()
    ) { innerPadding ->
        if (isReminderVisible) {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(innerPadding)
                    .padding(24.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Spacer(modifier = Modifier.height(40.dp))

                Text(
                    text = currentTime,
                    fontSize = 48.sp,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.primary
                )

                Spacer(modifier = Modifier.height(16.dp))

                Text(
                    text = "Zeit für deine Medikamente!",
                    fontSize = 20.sp,
                    fontWeight = FontWeight.Medium
                )

                Spacer(modifier = Modifier.height(32.dp))

                if (medications.isEmpty()) {
                    // Keine Medikamente in DB → Hinweis anzeigen
                    Box(
                        modifier = Modifier.weight(1f),
                        contentAlignment = Alignment.Center
                    ) {
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Text("", fontSize = 48.sp)
                            Text("Keine Medikamente vorhanden", fontSize = 16.sp)
                            Text(
                                "Tippe auf ⚙️ um Medikamente hinzuzufügen",
                                fontSize = 13.sp,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                            )
                        }
                    }
                } else {
                    LazyColumn(
                        modifier = Modifier.weight(1f),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        items(medications) { item ->
                            MedicationItem(
                                item = item,
                                onCheckedChange = { viewModel.toggleMedication(item.id) }
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(24.dp))

                // Snooze Button - zeigt aktuelle Zeit + Zähler
                val snoozesLeft = viewModel.maxSnoozeCount - snoozeCountToday
                Button(
                    onClick = {
                        if (viewModel.canSnooze) {
                            viewModel.snooze()
                        } else {
                            showSnoozeDialog = true // Zeige Info: Max erreicht
                        }
                    },
                    modifier = Modifier.fillMaxWidth().height(56.dp),
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (viewModel.canSnooze)
                            MaterialTheme.colorScheme.secondary
                        else
                            MaterialTheme.colorScheme.surfaceVariant
                    )
                ) {
                    if (viewModel.canSnooze) {
                        Text(
                            "⏰ Snooze (${viewModel.snoozeMinutes} Min)  •  noch ${snoozesLeft}x",
                            fontSize = 16.sp
                        )
                    } else {
                        Text("⏰ Snooze nicht mehr verfügbar", fontSize = 16.sp)
                    }
                }

                // Einstellungs-Link für Snooze
                TextButton(onClick = { showSnoozeDialog = true }) {
                    Text(
                        "Snooze-Einstellungen",
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
                    )
                }

                Spacer(modifier = Modifier.height(8.dp))
            }
        } else {
            Box(
                modifier = Modifier.fillMaxSize().padding(innerPadding),
                contentAlignment = Alignment.Center
            ) {
                Column(
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    Text("✓ Erledigt!", fontSize = 32.sp, fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.primary)
                    Text("Alle Medikamente eingenommen", fontSize = 18.sp)
                    Spacer(modifier = Modifier.height(16.dp))
                    TextButton(onClick = { viewModel.resetReminder() }) {
                        Text("Zurücksetzen (Test)")
                    }
                }
            }
        }
    }

    // Snooze-Einstellungs-Dialog
    if (showSnoozeDialog) {
        SnoozeSettingsDialog(
            currentMinutes = viewModel.snoozeMinutes,
            currentMaxCount = viewModel.maxSnoozeCount,
            context = LocalContext.current,
            onDismiss = { showSnoozeDialog = false }
        )
    }
}

@Composable
fun SnoozeSettingsDialog(
    currentMinutes: Int,
    currentMaxCount: Int,
    context: android.content.Context,
    onDismiss: () -> Unit
) {
    var selectedMinutes by remember { mutableIntStateOf(currentMinutes) }
    var selectedMaxCount by remember { mutableIntStateOf(currentMaxCount) }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text("⏰ Snooze-Einstellungen") },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(16.dp)) {
                Text("Snooze-Zeit:", fontWeight = FontWeight.Medium)
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceEvenly
                ) {
                    SnoozeManager.SNOOZE_OPTIONS.forEach { mins ->
                        FilterChip(
                            selected = selectedMinutes == mins,
                            onClick = { selectedMinutes = mins },
                            label = { Text("${mins}m") }
                        )
                    }
                }
                Text("Maximal pro Tag:", fontWeight = FontWeight.Medium)
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceEvenly
                ) {
                    SnoozeManager.MAX_COUNT_OPTIONS.forEach { count ->
                        FilterChip(
                            selected = selectedMaxCount == count,
                            onClick = { selectedMaxCount = count },
                            label = { Text("${count}x") }
                        )
                    }
                }
                Text(
                    "Heute bereits ${SnoozeManager.getSnoozeCountToday(context)}x gesnoozed",
                    fontSize = 12.sp,
                    color = androidx.compose.ui.graphics.Color.Gray
                )
            }
        },
        confirmButton = {
            Button(onClick = {
                SnoozeManager.setSnoozeMinutes(context, selectedMinutes)
                SnoozeManager.setMaxSnoozeCount(context, selectedMaxCount)
                onDismiss()
            }) { Text("Speichern") }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text("Abbrechen") }
        }
    )
}

@Composable
fun MedicationItem(
    item: MedicationCheckItem,
    onCheckedChange: (Boolean) -> Unit
) {
    Card(
        modifier = Modifier.fillMaxWidth(),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
    ) {
        Row(
            modifier = Modifier.fillMaxWidth().padding(16.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Checkbox(
                checked = item.isChecked,
                onCheckedChange = onCheckedChange
            )
            Spacer(modifier = Modifier.width(12.dp))
            Column(modifier = Modifier.weight(1f)) {
                Text(text = item.name, fontSize = 18.sp, fontWeight = FontWeight.Medium)
                val dosage = item.dosage
                if (!dosage.isNullOrBlank()) {
                    Text(text = dosage, fontSize = 13.sp,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f))
                }
            }
        }
    }
}

fun getCurrentTime(): String {
    val sdf = SimpleDateFormat("HH:mm", Locale.GERMAN)
    return sdf.format(Date())
}

@Preview(showBackground = true)
@Composable
fun MedicationReminderPreview() {
    MyMedTheme {
        MedicationReminderScreen()
    }
}

